import{_ as a,C as n,c as s,o as i,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"First steps with Manufacturing","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/get-started/first-steps.md","filePath":"master/supply-chain/manufacturing/get-started/first-steps.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/get-started/first-steps.md"};function d(h,t,p,u,c,g){const r=n("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="first-steps-with-manufacturing" tabindex="-1">First steps with Manufacturing <a class="header-anchor" href="#first-steps-with-manufacturing" aria-label="Permalink to &quot;First steps with Manufacturing&quot;">​</a></h1><p>This tutorial follows one build from start to end. You check the recipe, create a manufacturing order, confirm it, plan it, run the work orders and produce the finished goods. Each step links to a deeper page.</p><blockquote><p><strong>In simple words:</strong> Check the recipe, order a build, plan it, do the work, produce.</p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BoM  →  MO (Draft)  →  Confirm  →  Plan  →  Work orders  →  Produce All  →  Done</span></span></code></pre></div><p>The example builds the <strong>Business Laptop</strong>. <strong>Work Orders</strong> is on, so the recipe has two operations. The components are in stock.</p><h2 id="step-1-check-the-bill-of-materials" tabindex="-1">Step 1: Check the bill of materials <a class="header-anchor" href="#step-1-check-the-bill-of-materials" aria-label="Permalink to &quot;Step 1: Check the bill of materials&quot;">​</a></h2><p>The bill of materials (BoM) is the recipe. It lists what one laptop needs.</p><ol><li>Go to <code>Manufacturing → Products → Bills of Materials</code>.</li><li>Open <strong>BOM-MC-LAPTOP</strong>.</li><li>Check the <strong>Components</strong> tab: Motherboard, RAM 16GB (2), SSD 512GB, Laptop Battery, LCD Screen 14-inch and Laptop Chassis.</li><li>Open the <strong>Operations</strong> tab: <strong>Assemble Components</strong> at Assembly Station, then <strong>Test &amp; Pack</strong> at Quality &amp; Packing.</li></ol>',8)),o(r,{src:"/images1/manufacturing/first_bom_view.png",alt:"BOM-MC-LAPTOP view page with the Components tab open showing all six components and quantities"}),t[1]||(t[1]=e('<p>See <a href="./../basic-setup/bill-of-materials.html">Bill of materials</a>.</p><h2 id="step-2-create-the-manufacturing-order" tabindex="-1">Step 2: Create the manufacturing order <a class="header-anchor" href="#step-2-create-the-manufacturing-order" aria-label="Permalink to &quot;Step 2: Create the manufacturing order&quot;">​</a></h2><ol><li>Go to <code>Manufacturing → Operations → Manufacturing Orders</code> and click <strong>Create Manufacturing Order</strong>.</li><li>Choose <strong>Product</strong> <strong>Business Laptop</strong>. The <strong>Bill of Material</strong> fills in.</li><li>Enter <strong>Quantity</strong> 5. Check <strong>Scheduled Date</strong>.</li><li>Look at the <strong>Components</strong> tab. It lists the parts for 5 laptops. The <strong>Work Orders</strong> tab lists the two operations.</li><li>Click <strong>Create</strong>.</li></ol>',3)),o(r,{src:"/images1/manufacturing/first_mo_create.png",alt:"New MO form with Business Laptop, BOM-MC-LAPTOP, Quantity 5, Components tab showing scaled quantities"}),t[2]||(t[2]=e('<p>The order gets a number like <strong>MO/1</strong> and the state <strong>Draft</strong>. See <a href="./../workflows/manufacturing-orders.html">Manufacturing orders</a>.</p><h2 id="step-3-confirm" tabindex="-1">Step 3: Confirm <a class="header-anchor" href="#step-3-confirm" aria-label="Permalink to &quot;Step 3: Confirm&quot;">​</a></h2><ol><li>Click <strong>Confirm</strong> in the header and accept the prompt.</li></ol>',3)),o(r,{src:"/images1/manufacturing/first_mo_confirm.png",alt:"MO header with Confirm button and the confirmation prompt"}),t[3]||(t[3]=e('<p>You see &quot;Manufacturing order confirmed&quot;. The state becomes <strong>Confirmed</strong> and the components are reserved. The <strong>MO Readiness</strong> shows <strong>Ready</strong> when everything is in stock.</p><h2 id="step-4-plan" tabindex="-1">Step 4: Plan <a class="header-anchor" href="#step-4-plan" aria-label="Permalink to &quot;Step 4: Plan&quot;">​</a></h2><p>Planning gives each work order a start and end time on its work center.</p><ol><li>Click <strong>Plan</strong>.</li></ol>',4)),o(r,{src:"/images1/manufacturing/first_mo_planned.png",alt:"Confirmed MO after Plan with Unplan button visible and Work Orders tab showing Start and End dates"}),t[4]||(t[4]=e('<p>You see &quot;Manufacturing order planned&quot;. Open the <strong>Work Orders</strong> tab to read the dates. Click <strong>Unplan</strong> to undo. See <a href="./../workflows/plan-and-schedule.html">Plan and schedule</a>.</p><h2 id="step-5-run-the-work-orders" tabindex="-1">Step 5: Run the work orders <a class="header-anchor" href="#step-5-run-the-work-orders" aria-label="Permalink to &quot;Step 5: Run the work orders&quot;">​</a></h2><ol><li>Go to <code>Manufacturing → Operations → Work Orders</code>.</li><li>Find <strong>Assemble Components</strong> for the order. Click the start icon.</li><li>Click the done icon when it is finished.</li><li>Do the same for <strong>Test &amp; Pack</strong>.</li></ol>',3)),o(r,{src:"/images1/manufacturing/first_wo_list.png",alt:"Work Orders list with the MO/1 rows, one Finished and one In Progress"}),t[5]||(t[5]=e('<p>The order moves to <strong>In Progress</strong> after the first start. See <a href="./../workflows/work-orders.html">Work orders</a>.</p><h2 id="step-6-produce" tabindex="-1">Step 6: Produce <a class="header-anchor" href="#step-6-produce" aria-label="Permalink to &quot;Step 6: Produce&quot;">​</a></h2><ol><li>Open the order and click <strong>Produce All</strong>.</li><li>If a <strong>Consumption Warning</strong> appears, check the quantities and click <strong>Confirm</strong>.</li></ol>',3)),o(r,{src:"/images1/manufacturing/first_mo_done.png",alt:"MO in Done state with the stepper showing Done and Quantity Producing 5"}),t[6]||(t[6]=e('<p>You see &quot;Manufacturing order completed&quot;. The state becomes <strong>Done</strong>. Components are used up and 5 Business Laptops are in stock. See <a href="./../workflows/produce-and-consume.html">Produce and consume</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Confirm</td><td>Stock moves are created for each component. A pick transfer such as <strong>WH/PC/16</strong> can appear</td></tr><tr><td>Plan</td><td>Work orders get dates from the work center <strong>Working Hours</strong></td></tr><tr><td>Produce All</td><td>Components go from Stock through Pre-Production to Production. Finished goods enter stock</td></tr></tbody></table><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Result</th></tr></thead><tbody><tr><td>Check BoM</td><td>You know the recipe</td></tr><tr><td>Create</td><td><strong>Draft</strong> order <strong>MO/1</strong></td></tr><tr><td>Confirm</td><td><strong>Confirmed</strong>, components reserved</td></tr><tr><td>Plan</td><td>Dates on work orders</td></tr><tr><td>Work</td><td><strong>In Progress</strong></td></tr><tr><td>Produce All</td><td><strong>Done</strong></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manufacturing-settings.html">Manufacturing settings</a></li><li><a href="./../">Manufacturing overview</a></li><li><a href="./../basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a></li><li><a href="./../workflows/lots-and-serial-numbers.html">Lots and serial numbers</a></li></ul>',7))])}const _=a(l,[["render",d]]);export{f as __pageData,_ as default};
